import{_ as i,o as t,c as l,ae as a}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"ACP Client Boundary Adapter","description":"","frontmatter":{"work_package_id":"WP02","title":"ACP Client Boundary Adapter","lane":"done","dependencies":["WP01"],"base_branch":"025-provider-adapter-interface-and-lifecycle-WP01","base_commit":"081484ebd513e9ed30cf48638b7f53e3d8115bee","created_at":"2026-03-01T13:33:20.498081+00:00","subtasks":["T006","T007","T008","T009","T010"],"phase":"Phase 1 - Core Providers","assignee":"","agent":"claude-haiku","shell_pid":"70465","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/025-provider-adapter-interface-and-lifecycle/tasks/WP02-acp-client-boundary-adapter.md","filePath":"specs/025-provider-adapter-interface-and-lifecycle/tasks/WP02-acp-client-boundary-adapter.md"}'),o={name:"specs/025-provider-adapter-interface-and-lifecycle/tasks/WP02-acp-client-boundary-adapter.md"};function r(s,e,n,c,d,u){return t(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="work-package-prompt-wp02-acp-client-boundary-adapter" tabindex="-1">Work Package Prompt: WP02 - ACP Client Boundary Adapter <a class="header-anchor" href="#work-package-prompt-wp02-acp-client-boundary-adapter" aria-label="Permalink to &quot;Work Package Prompt: WP02 - ACP Client Boundary Adapter&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement the ACP protocol client adapter for Claude/agent task execution with full run/cancel lifecycle.</li><li>Wire ACP task execution to the local bus with correlation ID propagation and result capture.</li><li>Integrate the policy gate (spec 023) as a pre-execute hook that blocks unauthorized actions before contacting ACP.</li><li>Deliver health monitoring for ACP providers with configurable intervals and state transitions.</li></ul><p>Success criteria:</p><ul><li>ACP client initializes against a mock ACP endpoint within 5s.</li><li>Task execution propagates correlation IDs end-to-end from bus request through ACP response.</li><li>Policy gate denial prevents ACP contact and returns a normalized policy-denied error.</li><li>Health check transitions between healthy/degraded/unavailable states are deterministic and bus-published.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/025-provider-adapter-interface-and-lifecycle/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/025-provider-adapter-interface-and-lifecycle/spec.md</code></li><li>WP01 outputs: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/adapter.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/registry.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/errors.ts</code></li></ul></li><li>Protocol bus: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/bus.ts</code></li></ul></li></ul><p>Constraints:</p><ul><li>TypeScript + Bun runtime.</li><li>Adapter overhead &lt; 10ms (p95) excluding ACP processing time.</li><li>Timeout handling must produce normalized PROVIDER_TIMEOUT errors, never unhandled promise rejections.</li><li>Fail-fast; no silent fallback to alternative providers within this adapter.</li><li>Coverage &gt;=85% with FR-025-003 traceability.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t006-implement-acp-client-adapter-with-run-cancel-lifecycle" tabindex="-1">Subtask T006 - Implement ACP client adapter with run/cancel lifecycle <a class="header-anchor" href="#subtask-t006-implement-acp-client-adapter-with-run-cancel-lifecycle" aria-label="Permalink to &quot;Subtask T006 - Implement ACP client adapter with run/cancel lifecycle&quot;">​</a></h3><ul><li>Purpose: Deliver the primary AI provider integration for Claude task execution.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/acp-client.ts</code>.</li><li>Implement <code>ACPClientAdapter</code> class implementing <code>ProviderAdapter&lt;ACPConfig, ACPExecuteInput, ACPExecuteOutput&gt;</code>.</li><li>Define <code>ACPConfig</code> type with fields: <code>endpoint: string</code>, <code>apiKeyRef: string</code> (credential store reference), <code>model: string</code>, <code>timeoutMs: number</code>, <code>maxRetries: number</code>.</li><li>Implement <code>init(config: ACPConfig)</code>: <ul><li>Resolve API key from credential store reference (spec 028 interface or stub).</li><li>Validate endpoint reachability with a lightweight probe request.</li><li>Set up internal ACP client state (connection pool, retry config).</li><li>Reject with <code>PROVIDER_INIT_FAILED</code> if init takes &gt; 5s or endpoint unreachable.</li></ul></li><li>Implement <code>execute(input: ACPExecuteInput, correlationId: string)</code>: <ul><li>Construct ACP request payload with correlation ID in metadata.</li><li>Send request to ACP endpoint with configured timeout.</li><li>Map ACP response to <code>ACPExecuteOutput</code> including token usage, model info, and result payload.</li><li>On timeout, throw <code>PROVIDER_TIMEOUT</code> normalized error.</li><li>On ACP error response, map to appropriate normalized error code.</li></ul></li><li>Implement <code>cancel(taskId: string)</code>: <ul><li>Send cancellation request to ACP endpoint for the given task.</li><li>If task already completed, return success (idempotent).</li><li>If cancellation fails, throw normalized error.</li></ul></li><li>Implement <code>terminate()</code>: <ul><li>Close connection pool.</li><li>Cancel any in-flight requests with <code>PROVIDER_TERMINATED</code> error.</li><li>Release all resources.</li></ul></li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/acp-client.ts</code></li></ul></li><li>Validation: <ul><li>ACP client compiles and implements <code>ProviderAdapter</code> interface.</li><li>Init succeeds with valid config, fails with normalized error on bad config.</li><li>Execute propagates correlation ID round-trip.</li><li>Timeout produces <code>PROVIDER_TIMEOUT</code>, not unhandled rejection.</li><li>Cancel is idempotent.</li><li>Terminate cleans up all resources.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t007-wire-acp-task-execution-to-local-bus-with-correlation" tabindex="-1">Subtask T007 - Wire ACP task execution to local bus with correlation <a class="header-anchor" href="#subtask-t007-wire-acp-task-execution-to-local-bus-with-correlation" aria-label="Permalink to &quot;Subtask T007 - Wire ACP task execution to local bus with correlation&quot;">​</a></h3><ul><li>Purpose: Ensure ACP task results are visible on the local bus with full traceability.</li><li>Steps: <ol><li>In <code>acp-client.ts</code>, after successful execute, publish result to bus: <ul><li>Topic: <code>provider.acp.execute.completed</code></li><li>Payload: correlation ID, task ID, result summary, token usage, duration.</li></ul></li><li>On execute failure, publish failure event: <ul><li>Topic: <code>provider.acp.execute.failed</code></li><li>Payload: correlation ID, error code, retryable flag, error message.</li></ul></li><li>On cancel, publish cancellation event: <ul><li>Topic: <code>provider.acp.execute.cancelled</code></li><li>Payload: correlation ID, task ID.</li></ul></li><li>Ensure all bus events use the originating correlation ID from the execute input.</li><li>Import bus from <code>apps/runtime/src/protocol/bus.ts</code> and use existing publish primitives.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/acp-client.ts</code></li></ul></li><li>Validation: <ul><li>Bus events are emitted for every execute outcome (success, failure, cancel).</li><li>Correlation IDs match between execute input and bus event payload.</li><li>No bus event is emitted without a correlation ID.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-integrate-policy-gate-pre-execute-hook" tabindex="-1">Subtask T008 - Integrate policy gate pre-execute hook <a class="header-anchor" href="#subtask-t008-integrate-policy-gate-pre-execute-hook" aria-label="Permalink to &quot;Subtask T008 - Integrate policy gate pre-execute hook&quot;">​</a></h3><ul><li>Purpose: Block unauthorized ACP actions before contacting the ACP endpoint.</li><li>Steps: <ol><li>Define a <code>PolicyGate</code> interface stub (or import from spec 023 if available): <ul><li><code>evaluate(action: string, context: PolicyContext): Promise&lt;PolicyDecision&gt;</code></li><li><code>PolicyDecision</code>: <code>{ allowed: boolean, reason?: string }</code>.</li></ul></li><li>In <code>ACPClientAdapter.execute()</code>, before constructing the ACP request: <ul><li>Call <code>policyGate.evaluate(&#39;provider.acp.execute&#39;, { correlationId, input summary })</code>.</li><li>If denied, throw <code>PROVIDER_POLICY_DENIED</code> normalized error with the denial reason.</li><li>Publish <code>provider.acp.policy.denied</code> bus event with correlation ID and reason.</li></ul></li><li>Make policy gate injectable via constructor for testability.</li><li>Default policy gate should be a pass-through (allow-all) stub until spec 023 delivers the real implementation.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/acp-client.ts</code></li></ul></li><li>Validation: <ul><li>Policy denial prevents ACP endpoint contact (no network call).</li><li>Policy denial produces normalized error with reason.</li><li>Bus event emitted on denial.</li><li>Default stub allows all actions (no blocking without explicit policy).</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-implement-acp-specific-health-check" tabindex="-1">Subtask T009 - Implement ACP-specific health check <a class="header-anchor" href="#subtask-t009-implement-acp-specific-health-check" aria-label="Permalink to &quot;Subtask T009 - Implement ACP-specific health check&quot;">​</a></h3><ul><li>Purpose: Monitor ACP endpoint availability and transition provider state accordingly.</li><li>Steps: <ol><li>In <code>ACPClientAdapter</code>, implement <code>health()</code>: <ul><li>Send lightweight health probe to ACP endpoint (e.g., models list or ping).</li><li>Track consecutive failures.</li><li>After 3 consecutive failures, transition to <code>degraded</code>.</li><li>After 5 consecutive failures, transition to <code>unavailable</code>.</li><li>On success after degraded/unavailable, reset failure count and transition to <code>healthy</code>.</li></ul></li><li>Publish health state transitions to bus: <ul><li>Topic: <code>provider.acp.health.changed</code></li><li>Payload: provider ID, previous state, new state, failure count, timestamp.</li></ul></li><li>Health check interval is configurable via <code>ACPConfig.healthCheckIntervalMs</code> (default 30000ms, minimum 5000ms).</li><li>Health probe timeout should be separate from execute timeout (default 5s).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/acp-client.ts</code></li></ul></li><li>Validation: <ul><li>Health transitions are deterministic (3 failures -&gt; degraded, 5 -&gt; unavailable, 1 success -&gt; healthy).</li><li>Bus events emitted only on state transitions, not on every check.</li><li>Configurable interval is respected.</li><li>Health probe timeout does not block execute calls.</li></ul></li><li>Parallel: Yes (after T006 skeleton is stable).</li></ul><h3 id="subtask-t010-add-integration-tests-for-acp-lifecycle" tabindex="-1">Subtask T010 - Add integration tests for ACP lifecycle <a class="header-anchor" href="#subtask-t010-add-integration-tests-for-acp-lifecycle" aria-label="Permalink to &quot;Subtask T010 - Add integration tests for ACP lifecycle&quot;">​</a></h3><ul><li>Purpose: Verify complete ACP lifecycle including init, execute, cancel, health, terminate against mock server.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/__tests__/acp-client.test.ts</code>.</li><li>Implement mock ACP server using Bun&#39;s HTTP server: <ul><li>Configurable response behavior (success, error, timeout, slow response).</li><li>Request logging for correlation ID verification.</li></ul></li><li>Test scenarios: <ul><li><strong>Init success</strong>: valid config, endpoint reachable -&gt; init completes.</li><li><strong>Init failure</strong>: unreachable endpoint -&gt; <code>PROVIDER_INIT_FAILED</code> within 5s.</li><li><strong>Execute success</strong>: task dispatched, result returned with correlation ID.</li><li><strong>Execute timeout</strong>: mock server delays beyond timeout -&gt; <code>PROVIDER_TIMEOUT</code>.</li><li><strong>Execute policy denied</strong>: mock policy gate denies -&gt; <code>PROVIDER_POLICY_DENIED</code>, no server contact.</li><li><strong>Cancel success</strong>: running task cancelled.</li><li><strong>Cancel idempotent</strong>: cancel already-completed task -&gt; success.</li><li><strong>Health transitions</strong>: simulate 3 failures -&gt; degraded, 5 -&gt; unavailable, recovery -&gt; healthy.</li><li><strong>Health bus events</strong>: verify bus events emitted on state transitions only.</li><li><strong>Terminate cleanup</strong>: verify no in-flight requests remain, connection pool closed.</li><li><strong>Correlation ID propagation</strong>: verify ID appears in request to mock server and in bus events.</li></ul></li><li>Map tests to requirements: <ul><li>FR-025-001 (lifecycle): init/execute/terminate tests.</li><li>FR-025-003 (ACP integration): all ACP-specific tests.</li><li>FR-025-009 (health checks): health transition tests.</li><li>FR-025-012 (policy gates): policy denied test.</li></ul></li><li>Ensure tests run via <code>bun test</code> or Vitest.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/__tests__/acp-client.test.ts</code></li></ul></li><li>Validation: <ul><li>All test scenarios pass.</li><li>Coverage &gt;=85% on acp-client.ts.</li><li>Each mapped FR has at least one test.</li></ul></li><li>Parallel: Yes (after T006 is stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Mock ACP server provides configurable behavior for all test scenarios.</li><li>Policy gate is injected as a mock for policy denial tests.</li><li>Bus events are captured via test spy/subscription for correlation verification.</li><li>Timeout tests use mock server delay to trigger timeout behavior deterministically.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: ACP SDK changes break adapter contract.</li><li>Mitigation: All tests use mock server; real ACP integration is validated in separate smoke test suite.</li><li>Risk: Policy gate interface changes when spec 023 delivers.</li><li>Mitigation: Policy gate is injected via interface; swap stub for real implementation when available.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm correlation IDs propagate from bus request through ACP call and back to bus event.</li><li>Confirm policy denial prevents any network call to ACP endpoint.</li><li>Confirm health state transitions are deterministic and bus-published only on transitions.</li><li>Confirm timeout produces normalized error, not unhandled rejection.</li><li>Confirm terminate cancels in-flight requests and releases resources.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:33:20Z – claude-haiku – shell_pid=70465 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:34:32Z – claude-haiku – shell_pid=70465 – lane=done – Implemented: ACP client adapter with all lifecycle methods</li></ul>',30)])])}const m=i(o,[["render",r]]);export{h as __pageData,m as default};
